def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            safe_bid = DAILY_SALARY * 0.75
        return float(min(budget, safe_bid))

    prev_bids = []
    urgent_prev_bids = []
    conservative_prev_bids = []

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_prev_bids.append(float(bid))
            else:
                conservative_prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_urgent_prev = max(urgent_prev_bids) if urgent_prev_bids else highest_prev
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    my_urgency = 0
    if hp <= 2:
        my_urgency += 3
    elif hp <= 4:
        my_urgency += 2
    elif hp <= 6:
        my_urgency += 1

    if no_water_days >= 1:
        my_urgency += 2

    if supply <= 16:
        market_pressure = 3
    elif supply <= 19:
        market_pressure = 2
    else:
        market_pressure = 1

    if day >= 8:
        my_urgency += 1

    if my_urgency >= 4:
        target = max(0.92 * DAILY_SALARY, highest_urgent_prev + 2.0, avg_prev * 0.95)
    elif my_urgency >= 2:
        if market_pressure >= 2:
            target = max(0.72 * DAILY_SALARY, highest_prev * 0.78 + 1.0, avg_prev * 0.82)
        else:
            target = max(0.58 * DAILY_SALARY, avg_prev * 0.7)
    else:
        if market_pressure >= 3:
            target = max(0.52 * DAILY_SALARY, highest_prev * 0.52)
        elif market_pressure == 2:
            target = max(0.42 * DAILY_SALARY, avg_prev * 0.45)
        else:
            target = DAILY_SALARY * 0.28

    rich_threats = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) > budget and opp.get('hp', 0) <= 4:
            rich_threats += 1
    if rich_threats >= 2 and my_urgency >= 2:
        target += 6.0

    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget * 0.72 + 4.0)

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest = max(prev_bids) if prev_bids else 0.0
    # Also keep second-highest to avoid fully mirroring the maximum
    sorted_bids = sorted(prev_bids) if prev_bids else []
    second_highest = sorted_bids[-2] if len(sorted_bids) >= 2 else highest

    # Pressure heuristic: if someone was bidding very high, competition is intense.
    intense = highest >= DAILY_SALARY * 1.45  # ~130+ based on meta traces

    # Supply pressure: lower supply means fewer winners/less water; bid more.
    # Use a smooth scaling between MIN_SUPPLY and MAX_SUPPLY.
    if supply <= MIN_SUPPLY:
        supply_factor = 1.0
    elif supply >= MAX_SUPPLY:
        supply_factor = 0.75
    else:
        supply_factor = 1.0 - 0.25 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # If we are at risk (low hp or many no-water days), we must secure water.
    urgent = (hp <= 2.0) or (no_water_days >= 2)

    # Target bid level
    if urgent:
        # Aggressive but capped by budget.
        target = DAILY_SALARY * (0.95 if not intense else 1.05) * supply_factor
    else:
        if intense:
            # Match near the lower of top two to win without always paying the max.
            target = (second_highest + 3.0) * 0.98
        else:
            # Moderate bid to beat low bidders.
            target = max(DAILY_SALARY * 0.55, highest * 0.75) * supply_factor

    # Final clamp
    bid = max(0.0, min(budget, target))

    # Avoid bidding too low when supply is scarce and others were bidding high.
    if supply <= MIN_SUPPLY and intense:
        floor_bid = min(budget, DAILY_SALARY * 0.9)
        if bid < floor_bid:
            bid = floor_bid

    # Ensure at least a minimal non-zero bid if budget allows
    if bid <= 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
